'use strict';
const $=id=>document.getElementById(id);
const state={lesson:'hira-0',index:0,mode:'listen',view:'practice',revealed:false,answered:false,heard:false,practised:new Set(),kana:'hiragana'};
let voice=null,utterance=null,speechToken=0,speechTimer=null,recorder=null,stream=null,recordURL=null,recordTimer=null,recordTick=null,recordStarted=0,recordGeneration=0,recordPending=false;
const lesson=()=>LESSONS.find(l=>l.id===state.lesson);
const current=()=>lesson().cards[state.index];
const currentKey=()=>`${state.lesson}:${state.index}`;
function text(id,value){$(id).textContent=value}
function status(id,value,error=false){text(id,value);$(id).classList.toggle('error',error)}
function shuffle(items){const result=[...items];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function fillLessons(){const groups=new Map();LESSONS.forEach(l=>{const key=l.stage==='Foundation'?(l.id.startsWith('kata')?'Katakana':'Hiragana & sounds'):l.stage;if(!groups.has(key)){const g=document.createElement('optgroup');g.label=key;groups.set(key,g);$('lesson-select').append(g)}const o=document.createElement('option');o.value=l.id;o.textContent=l.name;groups.get(key).append(o)});$('lesson-select').value=state.lesson}
function renderCard(){
 const l=lesson(),c=current(),show=state.mode==='speak'||state.revealed;
 text('lesson-stage',l.stage.toUpperCase());text('lesson-count',`${l.cards.length} practice cards`);text('card-position',`CARD ${String(state.index+1).padStart(2,'0')} / ${String(l.cards.length).padStart(2,'0')}`);
 text('card-prompt',state.mode==='speak'?'Listen, then say it yourself.':show?'Read it. Listen again. Make it familiar.':'Listen first. What do you hear?');
 text('japanese',show?c.jp:'•••');$('japanese').classList.toggle('phrase',show&&c.jp.length>8);
 text('reading',show?c.reading:'Listen, then choose below.');text('meaning',show?c.en:'');text('burmese',show?c.my:'အရင်နားထောင်ပြီး အဖြေရွေးပါ။');
 text('note-title',l.stage==='Foundation'?'Small sounds, big progress.':'Build a speaking habit.');
 text('note-en',l.noteEn||'Listen to the whole phrase. Repeat slowly, record yourself, then compare. Try again without looking.');
 text('note-my',l.noteMy||'အဆုံးထိ နားထောင်ပါ။ ဖြည်းဖြည်း လိုက်ပြောပြီး ကိုယ့်အသံကို အသံသွင်းပါ။ ပြန်နားထောင်ပြီး နှိုင်းယှဉ်ပါ။');
 $('listen-panel').hidden=state.mode!=='listen';$('speak-panel').hidden=state.mode!=='speak';
 document.querySelectorAll('[data-mode]').forEach(b=>{const selected=b.dataset.mode===state.mode;b.classList.toggle('selected',selected);b.setAttribute('aria-selected',selected);b.tabIndex=selected?0:-1});$('exercise').setAttribute('aria-labelledby',`${state.mode}-tab`);
 $('previous-button').disabled=state.index===0;text('next-button',state.index===l.cards.length-1?'Start again ↺':'Next card →');
 text('session-progress',`${state.practised.size} cards practised`);text('complete-button',state.practised.has(currentKey())?'Practised ✓ / လေ့ကျင့်ပြီးပြီ':'I practised this / လေ့ကျင့်ပြီးပြီ');
 $('reveal-button').hidden=state.revealed;$('reveal-button').disabled=!state.heard;
}
function makeChoices(){
 $('answers').replaceChildren();const c=current();let candidates=lesson().cards.filter(x=>x.jp!==c.jp);
 if(candidates.length<2)candidates=LESSONS.filter(l=>l.stage==='Foundation').flatMap(l=>l.cards).filter(x=>x.jp!==c.jp);
 const unique=[...new Map(candidates.map(x=>[x.jp,x])).values()];const options=shuffle([c,...shuffle(unique).slice(0,2)]);
 options.forEach(x=>{const b=document.createElement('button');b.className='answer';b.lang='ja';b.textContent=x.jp;b.disabled=!state.heard;b.addEventListener('click',()=>{if(state.answered)return;if(x.jp===c.jp){state.answered=true;state.revealed=true;state.practised.add(currentKey());window.NihongoAccount?.complete(currentKey());b.classList.add('correct');text('quiz-feedback','Correct! / မှန်ပါတယ်။ Now try saying it.');Array.from($('answers').children).forEach(el=>el.disabled=true);renderCard()}else{b.classList.add('wrong');b.disabled=true;text('quiz-feedback','Listen again and try another. / ထပ်နားထောင်ပြီး ပြန်ရွေးပါ။')}});$('answers').append(b)});
}
function resetCard(){stopSpeech();clearRecording();state.revealed=false;state.answered=false;state.heard=false;text('quiz-feedback','');status('audio-status',voice?`Ready · ${voice.name}`:'Enable a Japanese voice on your device to hear the examples. / ဂျပန်အသံကို စက်မှာ ထည့်ပါ။',!voice);renderCard();makeChoices()}
function chooseLesson(id){if(!LESSONS.some(l=>l.id===id))throw new Error('Unknown lesson');state.lesson=id;state.index=0;$('lesson-select').value=id;resetCard()}
function setMode(mode){if(!['listen','speak'].includes(mode))throw new Error('Unknown practice mode');stopSpeech();clearRecording();state.mode=mode;renderCard()}
function moveCard(step){state.index=(state.index+step+lesson().cards.length)%lesson().cards.length;resetCard()}
let selectedVoice='';try{selectedVoice=localStorage.getItem('nihongo-voice')||''}catch{}
function voiceQuality(v){return (/natural|neural|premium/i.test(v.name)?100:0)+(/enhanced|google|microsoft/i.test(v.name)?40:0)+(/nanami|keita|kyoko|otoya/i.test(v.name)?10:0)}
function updateVoices(){
 if(!('speechSynthesis' in window)){status('audio-status','Japanese speech is unavailable in this browser. Try Safari, Chrome or Edge.',true);return}
 const choices=speechSynthesis.getVoices().filter(v=>/^ja(?:[-_]|$)/i.test(v.lang)).sort((a,b)=>voiceQuality(b)-voiceQuality(a));
 voice=choices.find(v=>v.voiceURI===selectedVoice)||choices[0]||null;
 const select=$('voice-select');select.replaceChildren();const auto=document.createElement('option');auto.value='';auto.textContent='Automatic · best available';select.append(auto);
 choices.forEach(v=>{const option=document.createElement('option');option.value=v.voiceURI;option.textContent=v.name+(v.localService?' · device':' · online');select.append(option)});select.value=choices.some(v=>v.voiceURI===selectedVoice)?selectedVoice:'';
 if(!speechSynthesis.speaking)status('audio-status',voice?`Ready · ${voice.name}${voice.localService?'':' · internet needed'}`:'No Japanese voice available. Add a Japanese voice in your device’s speech settings.',!voice);
}
function stopSpeech(){speechToken++;clearTimeout(speechTimer);if('speechSynthesis'in window)speechSynthesis.cancel();utterance=null;document.querySelector('.sound-visual').classList.remove('playing');$('play-button').disabled=false}
function speakJapanese(value,source='practice'){
 if(recordPending||(recorder&&recorder.state==='recording')){status('audio-status','Stop recording before playing the example. / အသံသွင်းတာ အရင်ရပ်ပါ။');return false}
 stopSpeech();updateVoices();if(!voice){if(source==='kana')status('kana-status','A Japanese voice is unavailable. Enable Japanese speech on your device, then reopen this page. / ဂျပန်အသံ ထည့်ပြီး ပြန်ဖွင့်ပါ။',true);return false}
 const token=speechToken;utterance=new SpeechSynthesisUtterance(value);utterance.voice=voice;utterance.lang='ja-JP';utterance.rate=Number($('speed').value)*0.95;utterance.pitch=1;
 const finish=()=>{if(token!==speechToken)return;clearTimeout(speechTimer);document.querySelector('.sound-visual').classList.remove('playing');$('play-button').disabled=false};
 utterance.onstart=()=>{if(token!==speechToken)return;clearTimeout(speechTimer);document.querySelector('.sound-visual').classList.add('playing');status('audio-status','Playing Japanese… / ဂျပန်အသံ နားထောင်ပါ။');if(source==='practice'){state.heard=true;Array.from($('answers').children).forEach(b=>b.disabled=state.answered||b.classList.contains('wrong'));$('reveal-button').disabled=false}};
 utterance.onend=()=>{finish();if(token===speechToken){status('audio-status','Play again whenever you need. / လိုသလောက် ထပ်နားထောင်ပါ။');if(source==='kana')status('kana-status','Now repeat the sound. / အသံထွက် လိုက်ပြောပါ။')}};
 utterance.onerror=e=>{finish();if(token===speechToken&&!['canceled','interrupted'].includes(e.error))status('audio-status','Could not play audio. Check sound settings and try again. / အသံဆက်တင် စစ်ပြီး ပြန်စမ်းပါ။',true)};
 $('recording').pause();$('play-button').disabled=true;speechSynthesis.speak(utterance);speechTimer=setTimeout(()=>{if(token===speechToken){stopSpeech();status('audio-status','Audio did not start. Try another browser or enable a Japanese voice. / ဂျပန်အသံ မစနိုင်ပါ။',true)}},7000);return true;
}
function stopRecording(){clearTimeout(recordTimer);clearInterval(recordTick);if(recorder&&recorder.state!=='inactive')recorder.stop();if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}$('record-button').classList.remove('recording');text('record-button','● Record again / ပြန်အသံသွင်း');}
function clearRecording(){recordGeneration++;stopRecording();recordPending=false;recorder=null;if(recordURL){URL.revokeObjectURL(recordURL);recordURL=null}$('recording').pause();$('recording').removeAttribute('src');$('recording').hidden=true;$('record-button').disabled=false;text('record-button','● Record my voice');status('record-status','Your recording stays in this tab. It is not uploaded. / အသံဖိုင်ကို ဒီစာမျက်နှာထဲမှာပဲ ထားပါတယ်။')}
async function recordVoice(){
 if(recorder&&recorder.state==='recording'){stopRecording();return}if(recordPending)return;
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){status('record-status','Recording is unavailable here. Open the site in a browser with microphone support. / မိုက်ခရိုဖုန်း ပံ့ပိုးတဲ့ browser မှာ ဖွင့်ပါ။',true);return}
 stopSpeech();$('recording').pause();recordPending=true;$('record-button').disabled=true;status('record-status','Allow microphone access to record your voice. / အသံသွင်းဖို့ မိုက်ခရိုဖုန်း ခွင့်ပြုပါ။');const gen=recordGeneration;
 try{const incoming=await navigator.mediaDevices.getUserMedia({audio:true});if(gen!==recordGeneration){incoming.getTracks().forEach(t=>t.stop());return}stream=incoming;
 if(recordURL){URL.revokeObjectURL(recordURL);recordURL=null}$('recording').hidden=true;
 const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(x=>MediaRecorder.isTypeSupported(x));const r=new MediaRecorder(stream,mime?{mimeType:mime}:{});recorder=r;const chunks=[];
 r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
 r.onstop=()=>{if(gen!==recordGeneration)return;clearTimeout(recordTimer);clearInterval(recordTick);if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}const blob=new Blob(chunks,{type:r.mimeType||'audio/webm'});if(!blob.size){status('record-status','No audio was captured. Please try again. / အသံမရပါ။ ပြန်စမ်းပါ။',true);return}recordURL=URL.createObjectURL(blob);$('recording').src=recordURL;$('recording').hidden=false;status('record-status','Ready. Play your recording and compare with the example. / ကိုယ့်အသံကို ပြန်နားထောင်ပြီး နှိုင်းယှဉ်ပါ။');$('record-button').classList.remove('recording');text('record-button','● Record again / ပြန်အသံသွင်း')};
 r.onerror=()=>{stopRecording();status('record-status','Recording failed. Please try again. / အသံသွင်းမရပါ။ ပြန်စမ်းပါ။',true)};
 r.start();recordStarted=Date.now();$('record-button').classList.add('recording');text('record-button','■ Stop recording / ရပ်မယ်');status('record-status','Recording… 0:00 / အသံသွင်းနေပါတယ်။');recordTick=setInterval(()=>{const sec=Math.floor((Date.now()-recordStarted)/1000);status('record-status',`Recording… 0:${String(sec).padStart(2,'0')} / အသံသွင်းနေပါတယ်။ (60 seconds max)`);},1000);recordTimer=setTimeout(stopRecording,60000);
 }catch(e){if(gen!==recordGeneration)return;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}const denied=['NotAllowedError','SecurityError'].includes(e.name);status('record-status',denied?'Microphone access was not allowed. Enable it in browser settings, then try again. / မိုက်ခရိုဖုန်း ခွင့်ပြုပြီး ပြန်စမ်းပါ။':'Microphone unavailable. Check that it is connected and try again. / မိုက်ခရိုဖုန်း စစ်ပြီး ပြန်စမ်းပါ။',true)}finally{if(gen===recordGeneration){recordPending=false;$('record-button').disabled=false}}
}
const pages={practice:['Listen & speak','နားထောင်၊ လိုက်ပြော၊ အသံသွင်းပြီး ပြန်နားထောင်ပါ။'],kana:['Kana library','Tap a character. Hear its sound. Repeat it aloud.'],plan:['My study plan','Six months of steady practice, around your weekly commitments.'],resources:['Learning resources','A few useful sources, with a clear way to practise.']};
function navigate(view){if(!pages[view])throw new Error('Unknown page');stopSpeech();clearRecording();state.view=view;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==`${view}-view`);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});text('page-title',pages[view][0]);text('page-subtitle',pages[view][1]);}
function renderKana(){const root=$('kana-view');root.innerHTML='<div class="panel"><h2>46 basic sounds / အခြေခံအက္ခရာ ၄၆ လုံး</h2><p>Learn hiragana first, then match the same sounds in katakana.</p><p lang="my">ဟီရဂနကို အရင်လေ့လာပြီး တူညီတဲ့အသံရှိတဲ့ ကတကနနဲ့ ယှဉ်ကြည့်ပါ။</p><div class="kana-switch"><button class="secondary selected" data-script="hiragana" aria-pressed="true">Hiragana / ひらがな</button><button class="secondary" data-script="katakana" aria-pressed="false">Katakana / カタカナ</button></div><p id="kana-status" class="status" role="status">Tap any character to hear it. / အက္ခရာကို နှိပ်ပြီး နားထောင်ပါ။</p><div id="kana-grid" class="kana-grid"></div></div><div class="panel"><h2>Small marks change the sound.</h2><p><span lang="ja">か → が　は → ぱ　き + ゃ → きゃ</span></p><p>Small っ creates a brief pause: きって (kit-te). In katakana, ー lengthens the previous vowel: コーヒー (kō-hī).</p><p lang="my">っ အသေးမှာ ခဏရပ်ပါ။ ကတကနမှာ ー က ရှေ့က သရသံကို ရှည်စေပါတယ်။</p><button class="secondary" id="sound-practice">Practise sound changes →</button></div>';
 function grid(){const target=$('kana-grid');target.replaceChildren();KANA_ROWS.forEach(r=>{const chars=[...r[state.kana==='hiragana'?1:2]];for(let j=0;j<5;j++){if(!chars[j]){const s=document.createElement('span');target.append(s);continue}const b=document.createElement('button');b.className='kana-key';b.setAttribute('aria-label',`${chars[j]}, ${r[3][j]}`);const jp=document.createElement('span');jp.lang='ja';jp.textContent=chars[j];const small=document.createElement('small');small.textContent=r[3][j];b.append(jp,small);b.onclick=()=>{target.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');speakJapanese(chars[j],'kana')};target.append(b)}})}
 root.querySelectorAll('[data-script]').forEach(b=>b.onclick=()=>{state.kana=b.dataset.script;root.querySelectorAll('[data-script]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});grid()});$('sound-practice').onclick=()=>{chooseLesson('sound-changes');navigate('practice')};grid();}
function renderPlan(){$('plan-view').innerHTML=`<div class="roadmap"><div><span class="eyebrow">WEEKS 1–4</span><strong>Rebuild N5</strong><p>Kana, particles, verb forms, everyday vocabulary.</p><p lang="my">N5 အခြေခံ ပြန်လေ့လာပါ။</p></div><div><span class="eyebrow">WEEKS 5–12</span><strong>Build your N4</strong><p>Grammar, kanji, short reading and daily listening.</p><p lang="my">N4 ကို အဆင့်လိုက် လေ့လာပါ။</p></div><div><span class="eyebrow">WEEKS 13–20</span><strong>Explore N3</strong><p>Longer texts, conversations and expressing ideas.</p><p lang="my">N3 စာနဲ့ စကားပြော လေ့ကျင့်ပါ။</p></div><div><span class="eyebrow">WEEKS 21–26</span><strong>Practise & review</strong><p>Timed tests, mistake review and weaker topics.</p><p lang="my">အစမ်းဖြေပြီး အမှားတွေ ပြန်လေ့လာပါ။</p></div></div><h2 class="section-title">Your weekly timetable / တစ်ပတ် အချိန်ဇယား</h2><div class="panel"><div class="table-scroll"><table><thead><tr><th>DAY</th><th>YOUR COMMITMENTS</th><th>STUDY SESSIONS</th></tr></thead><tbody><tr><td>Monday</td><td>Class · 8–11 am</td><td>1–2 pm: vocabulary & kanji<br>2:15–3:15 pm: grammar<br>7–7:30 pm: listen & speak</td></tr><tr><td>Tuesday</td><td>—</td><td>9–10 am: vocabulary & kanji<br>10:15–11:15 am: grammar<br>7–8 pm: reading, listening & speaking</td></tr><tr><td>Wednesday</td><td>Class · 1–4 pm</td><td>9–10 am: vocabulary & kanji<br>10:15–11:15 am: reading<br>7–7:30 pm: listen & speak</td></tr><tr><td>Thursday</td><td>Class · 1–4 pm*</td><td>9–10 am: vocabulary & kanji<br>10:15–11:15 am: grammar<br>7–7:30 pm: listen & speak</td></tr><tr><td>Friday</td><td>—</td><td>9–10 am: vocabulary & kanji<br>10:15–11:15 am: grammar exercises<br>7–8 pm: reading, listening & speaking</td></tr><tr><td>Saturday</td><td>—</td><td>9–10 am: review<br>10:15–11:15 am: practice questions<br>2–3 pm: correct mistakes</td></tr><tr><td>Sunday</td><td>Church · 8–11 am</td><td>4–5:30 pm: light review & listening</td></tr></tbody></table></div><p class="privacy">18 hours per week. *Thursday’s class is assumed to be 1–4 pm, as in your original plan.</p><p lang="my" class="privacy">တစ်ပတ် ၁၈ နာရီ။ ကြာသပတေးအတန်းချိန်ကို နေ့လယ် ၁–၄ နာရီလို့ ယူဆထားပါတယ်။</p></div><div class="panel"><h2>Check your understanding, not just your streak.</h2><p>Review N5 at week 4 and N4 at week 12. Adjust the pace if a foundation is still difficult. This site provides selected listening and speaking practice; N3 preparation also needs vocabulary, kanji, grammar, reading and test practice. Level labels are study guides, not official classifications.</p><p lang="my">အပတ် ၄ မှာ N5၊ အပတ် ၁၂ မှာ N4 ကို စစ်ဆေးပါ။ မရှင်းသေးရင် အချိန်ပိုပေးပါ။ N3 အတွက် ဝေါဟာရ၊ ခန်းဂျီး၊ သဒ္ဒါ၊ အဖတ်နဲ့ အစမ်းစာမေးပွဲလည်း လိုပါတယ်။</p></div>`}
function renderResources(){$('resources-view').innerHTML=`<div class="resource-grid"><article class="panel"><div class="resource-label">YOUTUBE · N5 · မြန်မာ</div><h2>Minna no Nihongo · Burmese</h2><p>N5 Minna no Nihongo grammar explained in Burmese. Study one grammar point, then practise with the matching cards.</p><p lang="my">Minna no Nihongo N5 သဒ္ဒါကို မြန်မာလို လေ့လာပါ။ သဒ္ဒါတစ်ခုစီကို သင်ပြီး သက်ဆိုင်တဲ့ ကတ်တွေနဲ့ လေ့ကျင့်ပါ။</p><a href="https://www.youtube.com/playlist?list=PLW-CHscMiiHc-8Piy5af26ic6ElMdy1l8" target="_blank" rel="noopener noreferrer">Open Burmese playlist ↗</a></article><article class="panel"><div class="resource-label">YOUTUBE · N5–N3 · ENGLISH</div><h2>NihonGoal</h2><p>English-guided N5–N3 grammar, vocabulary and kanji practice. Choose the level and topic you are studying.</p><p lang="my">N5 ကနေ N3 အထိ သဒ္ဒါ၊ ဝေါဟာရနဲ့ ခန်းဂျီးကို အင်္ဂလိပ်လို ရှင်းပြထားတဲ့ သင်ခန်းစာတွေ ကြည့်ပါ။</p><a href="https://www.youtube.com/@NihonGoal" target="_blank" rel="noopener noreferrer">Open NihonGoal ↗</a></article><article class="panel"><div class="resource-label">YOUTUBE · BEGINNER LESSONS</div><h2>Japanese Ammo with Misa</h2><p>Beginner Japanese lessons with English explanations. Start with the beginner playlist and match it to the grammar you are studying.</p><p lang="my">အင်္ဂလိပ်လို ရှင်းပြထားတဲ့ အခြေခံသင်ခန်းစာတွေကို ကြည့်ပါ။ ကိုယ်သင်နေတဲ့ သဒ္ဒါနဲ့ ကိုက်တဲ့ သင်ခန်းစာကို ရွေးပါ။</p><a href="https://www.youtube.com/@JapaneseAmmowithMisa" target="_blank" rel="noopener noreferrer">Open YouTube channel ↗</a></article><article class="panel"><div class="resource-label">OFFICIAL · EXAM PRACTICE</div><h2>JLPT sample questions</h2><p>Official sample questions from N5 to N3 and beyond. Use them to learn question formats and check your understanding.</p><p lang="my">တရားဝင် နမူနာမေးခွန်းတွေကို ဖြေပြီး မေးခွန်းပုံစံနဲ့ ရင်းနှီးအောင် လေ့ကျင့်ပါ။</p><a href="https://www.jlpt.jp/e/samples/forlearners.html" target="_blank" rel="noopener noreferrer">Try official questions ↗</a></article></div><div class="panel"><h2>Turn one short video into speaking practice.</h2><ol><li>Choose 20–60 seconds of clear Japanese from YouTube or social media.</li><li>Listen once without reading. / <span lang="my">စာမကြည့်ဘဲ နားထောင်ပါ။</span></li><li>Check the Japanese captions and look up unfamiliar words.</li><li>Pause after each phrase and repeat. / <span lang="my">ခဏရပ်ပြီး လိုက်ပြောပါ။</span></li><li>Say three useful phrases from memory. / <span lang="my">စကားစု ၃ ခုကို မကြည့်ဘဲ ပြန်ပြောပါ။</span></li></ol><p>Bring the link or Japanese text back to your lesson chat for English and Burmese explanations. Automatic captions can contain mistakes.</p><p lang="my">လင့်ခ် ဒါမှမဟုတ် ဂျပန်စာသားကို သင်ခန်းစာ chat မှာ ပို့ပြီး နှစ်ဘာသာနဲ့ ရှင်းပြခိုင်းနိုင်ပါတယ်။ အလိုအလျောက် စာတန်းမှာ အမှားရှိနိုင်ပါတယ်။</p></div><div class="panel"><h2>About the audio</h2><p>Choose a Japanese voice under Voice settings. Natural or enhanced voices are preferred when available. These are synthetic voices, and quality depends on your device. For human speech, use the linked native-speaker lessons and repeat short clips. Online voices need an internet connection.</p><p>Microphone recordings stay in this tab and are cleared when you change cards or close it. Recordings are not uploaded. Compare by listening; this site does not automatically score pronunciation.</p><p lang="my">ဥပမာအသံက စက်ရဲ့ ဂျပန်ကွန်ပျူတာအသံ ဖြစ်ပါတယ်။ ကိုယ့်အသံဖိုင်ကို server ဆီ မပို့ပါ။ ကတ်ပြောင်းရင် ဖျက်ပေးပါတယ်။ အသံထွက်ကို အလိုအလျောက် အမှတ်မပေးပါ။</p></div>`}
$('lesson-select').replaceChildren();fillLessons();renderKana();renderPlan();renderResources();updateVoices();resetCard();text('page-subtitle',pages.practice[1]);
$('voice-select').onchange=e=>{selectedVoice=e.target.value;try{localStorage.setItem('nihongo-voice',selectedVoice)}catch{}stopSpeech();updateVoices()};
$('lesson-select').onchange=e=>chooseLesson(e.target.value);$('play-button').onclick=()=>speakJapanese(current().speech);$('previous-button').onclick=()=>moveCard(-1);$('next-button').onclick=()=>moveCard(1);$('reveal-button').onclick=()=>{state.revealed=true;renderCard();text('quiz-feedback','Read the answer, then repeat it aloud. / အဖြေဖတ်ပြီး အသံထွက်ပြောပါ။')};$('record-button').onclick=recordVoice;$('complete-button').onclick=()=>{state.practised.add(currentKey());window.NihongoAccount?.complete(currentKey());renderCard()};
 document.querySelectorAll('[data-mode]').forEach(b=>{b.onclick=()=>setMode(b.dataset.mode);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'listen':e.key==='End'?'speak':state.mode==='listen'?'speak':'listen';setMode(next);$(`${next}-tab`).focus()}}});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('practice')};
if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',updateVoices);
window.addEventListener('pagehide',()=>{stopSpeech();clearRecording()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSpeech();if(recorder?.state==='recording')stopRecording()}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}};
 register({name:'get_practice_state',description:'Read available Japanese lessons and the current practice selection.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({lesson:state.lesson,card:state.index+1,mode:state.mode,practisedThisSession:state.practised.size,lessons:LESSONS.map(l=>({id:l.id,name:l.name,cards:l.cards.length}))})});
 register({name:'select_practice_lesson',description:'Open a Japanese lesson and choose listening or speaking practice. This does not play audio or activate the microphone.',inputSchema:{type:'object',properties:{lessonId:{type:'string'},mode:{type:'string',enum:['listen','speak']}},required:['lessonId','mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||!['listen','speak'].includes(input.mode)||!LESSONS.some(l=>l.id===input.lessonId))throw new Error('Choose a valid lessonId and mode.');chooseLesson(input.lessonId);setMode(input.mode);navigate('practice');return{lesson:state.lesson,mode:state.mode,card:1}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

window.addEventListener('progresschange',event=>{state.practised=new Set(event.detail.keys);renderCard()});
window.addEventListener('identitychange',()=>resetCard());
